local function tbl(t)
  return (type(t) == "table") and t or {}
end

function M.setup(opts)
  state = validate(vim.tbl_deep_extend("force", {}, state, tbl(opts)))
end

function M.get()
  return vim.tbl_deep_extend("force", {}, state)
end

function M.resolve(partial)
  local merged = vim.tbl_deep_extend("force", {}, state, tbl(partial))
  return validate(merged)
end

function M.format_display(it)
  return string.format(
    "%s:%d:%d — %s",
    vim.fn.fnamemodify(it.path, ":."),
    it.lnum,
    it.col0 + 1,
    it.line
  )
end

function U.get_ns()
  return vim.api.nvim_create_namespace("replacer_preview_ns")
end

function M.parse(content)
  local trimmed = vim.trim(content or "")
  if trimmed == "" then
    return nil, "batch: empty input"
  end
  if trimmed:sub(1, 1) == "[" then
    return parse_json(trimmed)
  end
  return parse_lines(content)
end

local function sanitize(path)
  return (path:gsub("[/\\:]", "_"))
end

function M.list()
  local ok, entries = pcall(vim.fn.readdir, checkpoints_dir())
  if not ok or type(entries) ~= "table" then
    return {}
  end
  table.sort(entries, function(a, b)
    return a > b
  end)
  return entries
end

function M.strip_cr(line)
  if line:sub(-1) == "\r" then
    return line:sub(1, -2)
  end
  return line
end

function M.new(typ, message, cause)
  return { type = typ, message = message, cause = cause }
end

function M.invalid_scope(message)
  return M.new("InvalidScopeError", message)
end

function M.write_error(message, cause)
  return M.new("WriteError", message, cause)
end

function M.search_error(message, cause)
  return M.new("SearchError", message, cause)
end

function M.safe_call(fn, ...)
  local ok, res = pcall(fn, ...)
  if ok then
    return { ok = true, result = res, err = nil }
  end
  return { ok = false, result = nil, err = M.new("RuntimeError", tostring(res), res) }
end

function M.format(err)
  if type(err) ~= "table" then
    return tostring(err)
  end
  return string.format("[%s] %s", err.type or "Error", err.message or "")
end

function M.build_json(results, new_text)
  local files = {}
  local total_spots = 0
  for _, r in ipairs(results) do
    total_spots = total_spots + r.spots
    local matches = {}
    for _, it in ipairs(r.matches) do
      matches[#matches + 1] = {
        lnum = it.lnum,
        col = it.col0 + 1,
        old = it.old,
        new = new_text,
        line = it.line,
      }
    end
    files[#files + 1] = {
      path = vim.fn.fnamemodify(r.path, ":."),
      spots = r.spots,
      skipped = r.skipped,
      matches = matches,
    }
  end
  return vim.json.encode({
    new_text = new_text,
    total_files = #results,
    total_spots = total_spots,
    files = files,
  })
end

function M.to_qf_entries(items)
  local entries = {}
  for i, it in ipairs(items) do
    entries[i] = {
      filename = it.path,
      lnum = it.lnum,
      col = it.col0 + 1,
      text = it.line,
      type = "I",
    }
  end
  return entries
end

function M.write_export(path, results, new_text)
  local is_json = path:lower():match("%.json$") ~= nil
  local content = is_json and M.build_json(results, new_text) or M.build_patch(results)

  return require("lib.nvim.fs.write.to_file")(path, content)
end

local function is_descendant_of(path, ancestor)
  return path:sub(1, #ancestor + 1) == (ancestor .. "/")
end

function M.build_preview(matches)
  local lines = {}
  for _, m in ipairs(matches) do
    lines[#lines + 1] = string.format(
      "%s  %s -> %s",
      m.is_dir and "[dir] " or "[file]",
      vim.fn.fnamemodify(m.old_path, ":."),
      vim.fn.fnamemodify(m.new_path, ":.")
    )
  end
  return table.concat(lines, "\n")
end

function M.register(run_fun)
  local usercmd = require("lib.nvim.usercmd")
  usercmd.create("ReplaceHistory", function()
    M.pick(run_fun)
  end, {
    desc = "Re-run a recent :Replace from history: :ReplaceHistory",
  })
end

function M.clear()
  for event in pairs(registered) do
    registered[event] = {}
  end
end

function M.looks_like_identifier(text)
  return text ~= nil and text ~= "" and text:match("^[%w_]+$") ~= nil
end

function M.escape(text)
  return vim.fn.escape(text or "", MAGIC_CHARS)
end

function M.has_backrefs(text)
  return text ~= nil and text:find("\\%d") ~= nil
end

local function post_filter(items, cfg)
  return apply_code_only(apply_word_boundary(apply_line_range(items, cfg), cfg), cfg)
end

local function and_filters(a, b)
  return function(m)
    return a(m) and b(m)
  end
end

function M.register(run_fun)
  local spec = {
    desc = "Wrap every match of a pattern: :[range]Surround[!] {pattern} [delim] [scope] [--flags]",
    bang = true,
    routes = {
      {
        path = {},
        args = {
          { name = "pattern", type = "STRING" },
          { name = "delim", type = "STRING", optional = true, values = DELIM_VALUES },
          {
            name = "scope",
            type = "STRING",
            optional = true,
            values = { "%", "cwd", ".", "root" },
          },
        },
        flags = FLAGS,
        range = true,
        run = function(ctx)
          handle(run_fun, ctx.raw, ctx.range)
        end,
      },
    },
  }

  composer.verb("Surround", spec)
  composer.verb("Wrap", spec)
end
